var numbers = new List<int> { 1, 2, 3 };
var evens = numbers.Where(n => n % 2 == 0);   // nothing runs yet

numbers.Add(4);
Console.WriteLine(string.Join(",", evens));   // 2,4 : sees the later Add

var snapshot = numbers.Where(n => n % 2 == 0).ToList();  // runs now, once
numbers.Add(6);
Console.WriteLine(snapshot.Count);            // 2 : a snapshot does not change
